const _doc = function doc(md){return(
md`# Alphametics Solver

Given an alphametics puzzle like \`SEND + MORE = MONEY\`, finds the digit assignment that makes the equation true.`
)};

const _solve = function solve(){return(
  function solve(puzzle) {
    const parts = puzzle.split(/\s*\+\s*|\s*=\s*/);
    const addends = parts.slice(0, -1).map(w => w.trim());
    const result = parts[parts.length - 1].trim();

    const letters = [...new Set(puzzle.match(/[A-Z]/g))];
    const n = letters.length;

    if (n > 10) return null;

    const leadingLetters = new Set([...addends, result].map(w => w[0]));

    const used = new Array(10).fill(false);
    const mapping = {};

    const wordToNum = (word) => {
      let num = 0;
      for (const ch of word) {
        num = num * 10 + mapping[ch];
      }
      return num;
    };

    function backtrack(idx) {
      if (idx === n) {
        const sum = addends.reduce((acc, w) => acc + wordToNum(w), 0);
        return sum === wordToNum(result) ? {...mapping} : null;
      }

      const letter = letters[idx];
      const start = leadingLetters.has(letter) ? 1 : 0;

      for (let d = start; d <= 9; d++) {
        if (!used[d]) {
          mapping[letter] = d;
          used[d] = true;
          const res = backtrack(idx + 1);
          if (res) return res;
          used[d] = false;
        }
      }

      return null;
    }

    return backtrack(0);
  }
)};

