const _cost = function cost(){
  const discounts = [0, 800, 1520, 2160, 2560, 3000];

  return function cost(books) {
    if (books.length === 0) return 0;

    // Count occurrences of each distinct book
    const countMap = {};
    for (const book of books) {
      countMap[book] = (countMap[book] || 0) + 1;
    }
    // Sort descending so greedy grouping picks the most-represented books
    const counts = Object.values(countMap).sort((a, b) => b - a);

    const memo = new Map();

    function minCost(c) {
      const key = c.join(',');
      if (memo.has(key)) return memo.get(key);

      const total = c.reduce((s, v) => s + v, 0);
      if (total === 0) return 0;

      let best = Infinity;
      const distinct = c.filter(v => v > 0).length;

      // Try every possible group size from 1 up to distinct books available
      for (let g = 1; g <= distinct; g++) {
        const next = c.slice();
        for (let i = 0; i < g; i++) next[i]--;
        next.sort((a, b) => b - a);
        const candidate = discounts[g] + minCost(next);
        if (candidate < best) best = candidate;
      }

      memo.set(key, best);
      return best;
    }

    return minCost(counts);
  };
};

