const _count = function count(){return( function countRectangles(lines) {
  if (!lines || lines.length === 0) return 0;

  const rows = lines.length;
  const cols = lines[0].length;

  // Collect all + positions per row for fast lookup
  const plusByRow = [];
  for (let r = 0; r < rows; r++) {
    const cols_in_row = [];
    for (let c = 0; c < cols; c++) {
      if (lines[r][c] === '+') cols_in_row.push(c);
    }
    plusByRow.push(cols_in_row);
  }

  // Check if horizontal segment from (r, c1) to (r, c2) is valid (all '-' or '+')
  function validH(r, c1, c2) {
    for (let c = c1 + 1; c < c2; c++) {
      const ch = lines[r][c];
      if (ch !== '-' && ch !== '+') return false;
    }
    return true;
  }

  // Check if vertical segment from (r1, c) to (r2, c) is valid (all '|' or '+')
  function validV(c, r1, r2) {
    for (let r = r1 + 1; r < r2; r++) {
      const ch = lines[r][c];
      if (ch !== '|' && ch !== '+') return false;
    }
    return true;
  }

  let total = 0;

  // For each row, consider all pairs of + as top-left (c1) and top-right (c2)
  for (let r1 = 0; r1 < rows; r1++) {
    const tops = plusByRow[r1];
    for (let i = 0; i < tops.length; i++) {
      const c1 = tops[i];
      for (let j = i + 1; j < tops.length; j++) {
        const c2 = tops[j];

        // Validate top horizontal edge
        if (!validH(r1, c1, c2)) continue;

        // Search for bottom row
        for (let r2 = r1 + 1; r2 < rows; r2++) {
          // Bottom-left must be +
          if (lines[r2][c1] !== '+') continue;
          // Bottom-right must be +
          if (lines[r2][c2] !== '+') continue;

          // Validate bottom horizontal edge
          if (!validH(r2, c1, c2)) continue;

          // Validate left vertical edge
          if (!validV(c1, r1, r2)) continue;

          // Validate right vertical edge
          if (!validV(c2, r1, r2)) continue;

          total++;
        }
      }
    }
  }

  return total;
})};


