class RestAPI {
  constructor(db) {
    // net[a][b] = how much b owes a (positive means b owes a)
    this.net = {};
    if (db && db.users) {
      for (const user of db.users) {
        for (const [person, amount] of Object.entries(user.owes || {})) {
          // user owes person `amount` => person lent user `amount`
          this._adjustLend(person, user.name, amount);
        }
      }
    }
  }

  _adjustLend(lender, borrower, amount) {
    if (!this.net[lender]) this.net[lender] = {};
    if (!this.net[borrower]) this.net[borrower] = {};
    this.net[lender][borrower] = (this.net[lender][borrower] || 0) + amount;
    this.net[borrower][lender] = (this.net[borrower][lender] || 0) - amount;
  }

  _buildUser(name) {
    const owes = {};
    const owed_by = {};
    let balance = 0;
    for (const [person, net] of Object.entries(this.net[name] || {})) {
      const rounded = Math.round(net * 100) / 100;
      if (rounded > 0) {
        owed_by[person] = rounded;
        balance += rounded;
      } else if (rounded < 0) {
        owes[person] = -rounded;
        balance += rounded;
      }
    }
    return { name, owes, owed_by, balance: Math.round(balance * 100) / 100 };
  }

