  return (board) => {
    const size = 3;

    // Count X's and O's and build grid
    let xCount = 0, oCount = 0;
    const grid = [];
    for (const row of board) {
      const cells = [...row];
      grid.push(cells);
      for (const cell of cells) {
        if (cell === 'X') xCount++;
        else if (cell === 'O') oCount++;
      }
    }

    // Validate turn order: X starts, so X count must equal O count or O count + 1
    if (xCount !== oCount && xCount !== oCount + 1) {
      throw new Error('Invalid board');
    }

    // Check if a player has a winning line
    const wins = (player) => {
      // Rows
      for (let r = 0; r < size; r++) {
        if (grid[r].every(c => c === player)) return true;
      }
      // Columns
      for (let c = 0; c < size; c++) {
        if (grid[0][c] === player && grid[1][c] === player && grid[2][c] === player) return true;
      }
      // Diagonals
      if (grid[0][0] === player && grid[1][1] === player && grid[2][2] === player) return true;
      if (grid[0][2] === player && grid[1][1] === player && grid[2][0] === player) return true;
      return false;
    };

    const xWins = wins('X');
    const oWins = wins('O');

    // Both players can't win (game would have ended when first player won)
    if (xWins && oWins) throw new Error('Invalid board');

    // If X won, X must have just played (X count = O count + 1)
